import{_ as d,C as l,o as i,c as h,a2 as s,E as o,w as r,a as e,j as n}from"./chunks/framework.D66Xq0Kv.js";const _=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md"}'),g={name:"guide/getting-started.md"};function c(u,t,p,f,w,T){const a=l("Screenshot");return i(),h("div",null,[t[8]||(t[8]=s('<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p>By the end of this guide a door in your level fades the screen, waits two seconds and plays a sound when the game starts. You create a FlowPilot asset, fill it with Tasks, and run it with a FlowPilot Component.</p><h2 id="_1-create-a-flowpilot-asset" tabindex="-1">1. Create a FlowPilot asset <a class="header-anchor" href="#_1-create-a-flowpilot-asset" aria-label="Permalink to &quot;1. Create a FlowPilot asset&quot;">​</a></h2><ol><li>In the Content Browser, right-click an empty area and open the <strong>Gameplay</strong> category.</li><li>Pick <strong>FlowPilot</strong> and name the asset, for example <code>FP_DoorIntro</code>.</li><li>Double-click the asset to open the FlowPilot Editor.</li></ol>',4)),o(a,{src:"images/create_flowpilot_asset.png"},{default:r(()=>[...t[0]||(t[0]=[e("Content Browser: Gameplay › FlowPilot.",-1)])]),_:1}),t[9]||(t[9]=s('<h2 id="_2-find-your-way-around-the-editor" tabindex="-1">2. Find your way around the editor <a class="header-anchor" href="#_2-find-your-way-around-the-editor" aria-label="Permalink to &quot;2. Find your way around the editor&quot;">​</a></h2><p>The editor has four panels. Every new asset starts with a Root Sequence named after the asset: everything you add goes under it.</p><table tabindex="0"><thead><tr><th>Panel</th><th>Where</th><th>What it is for</th></tr></thead><tbody><tr><td>Main Data</td><td>Top left</td><td>Asset settings, such as the Flow Name.</td></tr><tr><td>Tasks Palette</td><td>Bottom left</td><td>Every Task you can add, grouped by category, with a search box.</td></tr><tr><td>Tree View</td><td>Center</td><td>The flow itself: Tasks run top to bottom.</td></tr><tr><td>Task Details</td><td>Right</td><td>Settings of the selected Task, and its Class.</td></tr></tbody></table>',3)),o(a,{src:"screenshots/editor-overview.png"},{default:r(()=>[...t[1]||(t[1]=[e("The FlowPilot Editor with a small flow: Main Data, Tasks Palette, Tree View and Task Details.",-1)])]),_:1}),t[10]||(t[10]=s('<h2 id="_3-add-tasks" tabindex="-1">3. Add Tasks <a class="header-anchor" href="#_3-add-tasks" aria-label="Permalink to &quot;3. Add Tasks&quot;">​</a></h2><p>There are three ways to add a Task:</p><ul><li><strong>Drag and drop</strong> a Task from the Tasks Palette onto the Tree View. The label under the cursor tells you where it lands, e.g. <code>Add &#39;Delay&#39; after &#39;Screen Fade&#39;</code>. Drop on a Sequence to add inside it, or on empty space to add at the end of the flow.</li><li><strong>+ Add Task</strong> at the top of the Tree View opens a searchable list. Start typing to filter it.</li><li><strong>Double-click</strong> a Task in the Palette, or press its <strong>Add</strong> button.</li></ul><p>With Add Task and double-click, the new Task goes into the selected Task if it holds Tasks (Sequence, Selector, Parallel), and right after it otherwise. With nothing selected it goes at the end of the flow.</p><p>For the door, add <a href="/reference/tasks/screen-fade">Screen Fade</a>, then <a href="/reference/tasks/delay">Delay</a>, then <a href="/reference/tasks/play-sound">Play Sound</a>, and set their options in Task Details: the fade, 2 seconds of delay, and the sound to play.</p>',5)),o(a,{src:"screenshots/drag-from-palette.png"},{default:r(()=>[...t[2]||(t[2]=[e("Dragging a Task from the Palette: the drag label and the drop indicator.",-1)])]),_:1}),o(a,{src:"screenshots/add-task-menu.png"},{default:r(()=>[...t[3]||(t[3]=[e("The + Add Task menu, filtered by typing.",-1)])]),_:1}),t[11]||(t[11]=s('<h2 id="_4-organise-the-flow" tabindex="-1">4. Organise the flow <a class="header-anchor" href="#_4-organise-the-flow" aria-label="Permalink to &quot;4. Organise the flow&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>How</th></tr></thead><tbody><tr><td>Move Tasks</td><td>Drag them in the Tree View: above, below, or onto a Sequence to move inside it.</td></tr><tr><td>Rename</td><td>Select and press <kbd>F2</kbd>, or double-click a Task that has no children.</td></tr><tr><td>Skip a Task without deleting it</td><td>Disable it from the toolbar, the right-click menu or the row button. Disabled Tasks show <code>[Disabled]</code> and are skipped at runtime.</td></tr><tr><td>Copy, paste, duplicate</td><td><kbd>Ctrl+C</kbd>, <kbd>Ctrl+V</kbd>, <kbd>Ctrl+D</kbd>. Paste and duplicate place the copy next to the selection.</td></tr><tr><td>Delete</td><td><kbd>Delete</kbd>, or the Remove button (asks for confirmation).</td></tr><tr><td>Change a Task&#39;s type</td><td>Task Details › Class. Switching between Sequence, Selector and Parallel keeps the children.</td></tr><tr><td>Find a Task</td><td>The search bar above the tree matches names, descriptions and Task types.</td></tr><tr><td>Undo / redo</td><td><kbd>Ctrl+Z</kbd> / <kbd>Ctrl+Y</kbd> undo every change above, including Task Details edits.</td></tr></tbody></table><p>A warning icon on a Task means its settings are invalid: hover it to see why. Save the asset when you are done.</p>',3)),o(a,{src:"screenshots/tree-context-menu.png"},{default:r(()=>[...t[4]||(t[4]=[e("Right-click menu on a Task in the Tree View.",-1)])]),_:1}),o(a,{src:"screenshots/task-warning.png"},{default:r(()=>[...t[5]||(t[5]=[e("A Task with a warning icon, and its tooltip explaining the problem.",-1)])]),_:1}),t[12]||(t[12]=s('<h2 id="_5-run-the-flow-in-a-level" tabindex="-1">5. Run the flow in a level <a class="header-anchor" href="#_5-run-the-flow-in-a-level" aria-label="Permalink to &quot;5. Run the flow in a level&quot;">​</a></h2><ol><li>Open the Actor that should own the flow (the door Blueprint, or any Actor in the level) and add a <strong>FlowPilot Component</strong>.</li><li>Set <strong>Flow Pilot Asset</strong> to <code>FP_DoorIntro</code>.</li><li>Tick <strong>Auto Start On Begin Play</strong> to start when the game starts, or call <strong>Start Flow</strong> from Blueprint.</li><li>Press Play.</li></ol>',2)),o(a,{src:"images/fp-component-details.png"},{default:r(()=>[...t[6]||(t[6]=[e("FlowPilot Component settings on an Actor.",-1)])]),_:1}),t[13]||(t[13]=s('<p><strong>Execution Mode</strong> decides whether the flow restarts:</p><table tabindex="0"><thead><tr><th>Execution Mode</th><th>Behaviour</th></tr></thead><tbody><tr><td>Run Once</td><td>Runs the flow once.</td></tr><tr><td>Run Until Succeed / Run Until Fail</td><td>Restarts until the flow succeeds / fails once.</td></tr><tr><td>Run While Succeed / Run While Fail</td><td>Restarts as long as the flow keeps succeeding / failing.</td></tr><tr><td>Run Non Stop</td><td>Restarts forever.</td></tr></tbody></table><p><strong>Retry Delay</strong> waits between restarts. From Blueprint you can also <strong>Pause Flow</strong>, <strong>Un Pause Flow</strong>, <strong>Stop Flow</strong> and <strong>Set Flow Pilot Asset</strong>, and bind to <strong>On Flow Started</strong>, <strong>On Flow Completed</strong> and <strong>On Flow Error</strong>. See the <a href="/reference/components/flowpilot-component">FlowPilot Component reference</a>.</p><h2 id="_6-point-tasks-at-actors" tabindex="-1">6. Point Tasks at Actors <a class="header-anchor" href="#_6-point-tasks-at-actors" aria-label="Permalink to &quot;6. Point Tasks at Actors&quot;">​</a></h2><p>Tasks that act on Actors use a <a href="/reference/core/flow-actor-reference">Flow Actor Reference</a> with three scopes:</p><table tabindex="0"><thead><tr><th>Scope</th><th>Finds</th></tr></thead><tbody><tr><td>Self</td><td>The Actor that owns the FlowPilot Component.</td></tr><tr><td>In Level</td><td>An Actor you pick in the level.</td></tr><tr><td>Runtime</td><td>Actors with a GameplayTag, including Actors spawned during play (e.g. by <a href="/reference/tasks/spawn-class">Spawn Class</a> with Tags To Add Actor).</td></tr></tbody></table>',6)),o(a,{src:"screenshots/actor-reference-scope.png"},{default:r(()=>[...t[7]||(t[7]=[e("Task Details of a Task with an Actor reference, showing the Self / In Level / Runtime scopes.",-1)])]),_:1}),t[14]||(t[14]=n("p",null,[e("Next: "),n("a",{href:"./debugging"},"Debugging Flows"),e(".")],-1))])}const b=d(g,[["render",c]]);export{_ as __pageData,b as default};
